      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The harness masks options to supported bits but does not force CMARK_OPT_VALIDATE_UTF8. With that bit clear, S_process_line copies the supplied bytes into its line buffer.",
      "evidence": [
        {"unit_id": "u-01d44c1169261cd79a4c", "start_line": 16, "end_line": 22, "role": "primary", "dependency_reason": ""},
