      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "In the after scanner, byte 0xFF in a double quoted attribute is admitted by the high byte bitmap path. After the closing quote, '>', and newline, the scanner can return type 7.",
      "evidence": [
        {"unit_id": "u-a1a08cffd1ca26310e68", "start_line": 7167, "end_line": 7176, "role": "primary", "dependency_reason": ""},
