    {
      "topic": "counterevidence",
      "statement": "The before scanner rejects 0xFF on the double quoted attribute path: its high byte bitmap entries are zero, and a byte above 0xF4 takes the failure path.",
      "evidence": [
        {"unit_id": "u-b355481778f3add37dfc", "start_line": 8017, "end_line": 8026, "role": "primary", "dependency_reason": ""},
