      "audited_unit_ids": []
    },
    {
      "topic": "scope",
      "statement": "The scan_html_block_start_7 macro delegates to _scan_at, while S_process_line calls open_new_blocks. The supplied lines do not establish what _scan_at returns to that block parser call.",
      "evidence": [
        {"unit_id": "u-8dcbdd6d5c63141b4b6b", "start_line": 42, "end_line": 42, "role": "dependency", "dependency_reason": "The macro places _scan_at between the scanner and its caller."},
        {"unit_id": "u-f20dc521c971d4f66630", "start_line": 1299, "end_line": 1313, "role": "dependency", "dependency_reason": "Line processing reaches block opening after preparing the input."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
